import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  LineChart, Line, Legend, AreaChart, Area 
} from 'recharts';
import { 
  Activity, Clock, AlertTriangle, TrendingUp, Zap, 
  Globe, Server, RefreshCw, AlertCircle 
} from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { Button } from '@/components/ui/button';

interface ChatMetricsSummary {
  date: string;
  total_requests: number;
  avg_embedding_ms: number | null;
  avg_search_ms: number | null;
  avg_llm_first_token_ms: number | null;
  avg_llm_total_ms: number | null;
  fallback_count: number;
  rate_limit_hits: number;
  gemini_count: number;
  lovable_count: number;
  web_search_count: number;
  error_count: number;
}

interface FrontendErrorsSummary {
  date: string;
  total_errors: number;
  unique_messages: number;
  chrome_count: number;
  firefox_count: number;
  safari_count: number;
  edge_count: number;
  mobile_count: number;
  other_count: number;
}

export function ChatMetricsDashboard() {
  const [chatMetrics, setChatMetrics] = useState<ChatMetricsSummary[]>([]);
  const [frontendErrors, setFrontendErrors] = useState<FrontendErrorsSummary[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchMetrics = async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      const [chatResult, errorsResult] = await Promise.all([
        supabase.rpc('get_chat_metrics_summary', { p_days: 7 }),
        supabase.rpc('get_frontend_errors_summary', { p_days: 7 })
      ]);

      if (chatResult.error) throw chatResult.error;
      if (errorsResult.error) throw errorsResult.error;

      setChatMetrics((chatResult.data || []).reverse());
      setFrontendErrors((errorsResult.data || []).reverse());
    } catch (err: unknown) {
      console.error('[ChatMetricsDashboard] Error fetching metrics:', err);
      setError(err instanceof Error ? err.message : 'Erro ao carregar m├®tricas');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchMetrics();
  }, []);

  // Calculate summary stats from the most recent data
  const todayMetrics = chatMetrics[chatMetrics.length - 1];
  const totalRequests = chatMetrics.reduce((sum, d) => sum + d.total_requests, 0);
  const totalFallbacks = chatMetrics.reduce((sum, d) => sum + d.fallback_count, 0);
  const totalRateLimits = chatMetrics.reduce((sum, d) => sum + d.rate_limit_hits, 0);
  const totalErrors = frontendErrors.reduce((sum, d) => sum + d.total_errors, 0);
  const fallbackRate = totalRequests > 0 ? ((totalFallbacks / totalRequests) * 100).toFixed(1) : '0';
  
  // Calculate average latencies across all days
  const avgLatencies = chatMetrics.length > 0 ? {
    embedding: Math.round(chatMetrics.reduce((sum, d) => sum + (d.avg_embedding_ms || 0), 0) / chatMetrics.length),
    search: Math.round(chatMetrics.reduce((sum, d) => sum + (d.avg_search_ms || 0), 0) / chatMetrics.length),
    llmFirstToken: Math.round(chatMetrics.reduce((sum, d) => sum + (d.avg_llm_first_token_ms || 0), 0) / chatMetrics.length),
    llmTotal: Math.round(chatMetrics.reduce((sum, d) => sum + (d.avg_llm_total_ms || 0), 0) / chatMetrics.length),
  } : null;

  // Prepare latency chart data
  const latencyChartData = chatMetrics.map(d => ({
    date: new Date(d.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
    Embedding: d.avg_embedding_ms || 0,
    Busca: d.avg_search_ms || 0,
    'LLM (1┬║ token)': d.avg_llm_first_token_ms || 0,
  }));

  // Prepare provider chart data
  const providerChartData = chatMetrics.map(d => ({
    date: new Date(d.date).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }),
    Gemini: d.gemini_count,
    'Web Search': d.web_search_count,
  }));

  // Alerts
  const alerts: { type: 'warning' | 'error'; message: string }[] = [];
  if (parseFloat(fallbackRate) > 20) {
    alerts.push({ type: 'error', message: `Taxa de fallback alta: ${fallbackRate}%` });
  }
  if (totalRateLimits > 10) {
    alerts.push({ type: 'warning', message: `${totalRateLimits} hits de rate limit nos ├║ltimos 7 dias` });
  }
  if (totalErrors > 5) {
    alerts.push({ type: 'warning', message: `${totalErrors} erros de frontend nos ├║ltimos 7 dias` });
  }

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {[...Array(4)].map((_, i) => (
            <Card key={i} className="glass-card">
              <CardHeader className="pb-2">
                <Skeleton className="h-4 w-24" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-8 w-16" />
              </CardContent>
            </Card>
          ))}
        </div>
        <Card className="glass-card">
          <CardHeader>
            <Skeleton className="h-6 w-48" />
          </CardHeader>
          <CardContent>
            <Skeleton className="h-64 w-full" />
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error) {
    return (
      <Card className="glass-card">
        <CardContent className="py-12 text-center">
          <AlertCircle className="w-12 h-12 text-destructive mx-auto mb-4" />
          <p className="text-destructive font-medium">{error}</p>
          <Button onClick={fetchMetrics} variant="outline" className="mt-4">
            <RefreshCw className="w-4 h-4 mr-2" />
            Tentar novamente
          </Button>
        </CardContent>
      </Card>
    );
  }

  const hasData = chatMetrics.length > 0;

  return (
    <div className="space-y-6">
      {/* Alerts */}
      {alerts.length > 0 && (
        <div className="space-y-2">
          {alerts.map((alert, i) => (
            <div
              key={i}
              className={`flex items-center gap-3 p-3 rounded-lg ${
                alert.type === 'error' 
                  ? 'bg-destructive/10 border border-destructive/30' 
                  : 'bg-amber-500/10 border border-amber-500/30'
              }`}
            >
              <AlertTriangle className={`w-5 h-5 ${alert.type === 'error' ? 'text-destructive' : 'text-amber-500'}`} />
              <span className={alert.type === 'error' ? 'text-destructive' : 'text-amber-500'}>
                {alert.message}
              </span>
            </div>
          ))}
        </div>
      )}

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="glass-card">
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-2">
              <Activity className="w-4 h-4" />
              Total de Requests (7d)
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">{totalRequests}</p>
            {todayMetrics && (
              <p className="text-sm text-muted-foreground mt-1">
                {todayMetrics.total_requests} hoje
              </p>
            )}
          </CardContent>
        </Card>

        <Card className="glass-card">
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-2">
              <Clock className="w-4 h-4" />
              Lat├¬ncia M├®dia LLM
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {avgLatencies?.llmFirstToken || 0}
              <span className="text-lg text-muted-foreground">ms</span>
            </p>
            <p className="text-sm text-muted-foreground mt-1">
              1┬║ token ÔÇó Total: {avgLatencies?.llmTotal || 0}ms
            </p>
          </CardContent>
        </Card>

        <Card className="glass-card">
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-2">
              <TrendingUp className="w-4 h-4" />
              Taxa de Fallback
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className={`text-3xl font-bold ${parseFloat(fallbackRate) > 20 ? 'text-destructive' : ''}`}>
              {fallbackRate}%
            </p>
            <p className="text-sm text-muted-foreground mt-1">
              {totalFallbacks} de {totalRequests} requests
            </p>
          </CardContent>
        </Card>

        <Card className="glass-card">
          <CardHeader className="pb-2">
            <CardDescription className="flex items-center gap-2">
              <AlertTriangle className="w-4 h-4" />
              Rate Limits + Erros
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {totalRateLimits + totalErrors}
            </p>
            <div className="flex gap-2 mt-1">
              <Badge variant="secondary" className="text-xs">
                {totalRateLimits} RL
              </Badge>
              <Badge variant="secondary" className="text-xs">
                {totalErrors} erros
              </Badge>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Charts */}
      {hasData ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Latency Chart */}
          <Card className="glass-card">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-lg">
                <Zap className="w-5 h-5 text-primary" />
                Lat├¬ncia por Etapa (ms)
              </CardTitle>
              <CardDescription>
                M├®dia di├íria de lat├¬ncia por componente do pipeline
              </CardDescription>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={250}>
                <BarChart data={latencyChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis dataKey="date" stroke="hsl(var(--muted-foreground))" fontSize={12} />
                  <YAxis stroke="hsl(var(--muted-foreground))" fontSize={12} />
                  <Tooltip 
                    contentStyle={{ 
                      backgroundColor: 'hsl(var(--card))', 
                      border: '1px solid hsl(var(--border))',
                      borderRadius: '8px'
                    }}
                  />
                  <Legend />
                  <Bar dataKey="Embedding" fill="hsl(var(--primary))" stackId="a" />
                  <Bar dataKey="Busca" fill="hsl(var(--accent))" stackId="a" />
                  <Bar dataKey="LLM (1┬║ token)" fill="hsl(220, 70%, 50%)" stackId="a" />
                </BarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>

          {/* Provider Distribution */}
          <Card className="glass-card">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-lg">
                <Server className="w-5 h-5 text-primary" />
                Distribui├º├úo de Providers
              </CardTitle>
              <CardDescription>
                Volume de requests por provider e uso de web search
              </CardDescription>
            </CardHeader>
            <CardContent>
              <ResponsiveContainer width="100%" height={250}>
                <AreaChart data={providerChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis dataKey="date" stroke="hsl(var(--muted-foreground))" fontSize={12} />
                  <YAxis stroke="hsl(var(--muted-foreground))" fontSize={12} />
                  <Tooltip 
                    contentStyle={{ 
                      backgroundColor: 'hsl(var(--card))', 
                      border: '1px solid hsl(var(--border))',
                      borderRadius: '8px'
                    }}
                  />
                   <Legend />
                   <Area type="monotone" dataKey="Gemini" stackId="1" fill="hsl(var(--primary))" stroke="hsl(var(--primary))" />
                   <Area type="monotone" dataKey="Web Search" stackId="2" fill="hsl(220, 70%, 50%)" stroke="hsl(220, 70%, 50%)" fillOpacity={0.3} />
                 </AreaChart>
               </ResponsiveContainer>
            </CardContent>
          </Card>
        </div>
      ) : (
        <Card className="glass-card">
          <CardContent className="py-12 text-center">
            <Activity className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
            <p className="text-muted-foreground">Nenhuma m├®trica registrada ainda.</p>
            <p className="text-sm text-muted-foreground mt-1">
              As m├®tricas ser├úo exibidas ap├│s o primeiro chat.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Refresh Button */}
      <div className="flex justify-end">
        <Button onClick={fetchMetrics} variant="outline" size="sm">
          <RefreshCw className="w-4 h-4 mr-2" />
          Atualizar M├®tricas
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { CalendarIcon, X, Plus, Tag, History, Save, Loader2, Link2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface DocumentForEdit {
  id: string;
  title: string;
  tags?: string[] | null;
  version_label?: string | null;
  effective_date?: string | null;
  supersedes_document_id?: string | null;
}

interface DocumentListItem {
  id: string;
  title: string;
  supersedes_document_id?: string | null;
}

interface DocumentEditorModalProps {
  document: DocumentForEdit | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSaved: () => void;
  adminKey: string;
  allDocuments: DocumentListItem[];
}

export function DocumentEditorModal({
  document,
  open,
  onOpenChange,
  onSaved,
  adminKey,
  allDocuments,
}: DocumentEditorModalProps) {
  const { toast } = useToast();
  const [isSaving, setIsSaving] = useState(false);
  
  // Form state
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [versionLabel, setVersionLabel] = useState('');
  const [effectiveDate, setEffectiveDate] = useState<Date | undefined>();
  const [supersedesDocumentId, setSupersedesDocumentId] = useState<string>('');
  
  // Initialize form when document changes
  useEffect(() => {
    if (document) {
      setTags(document.tags || []);
      setVersionLabel(document.version_label || '');
      setEffectiveDate(document.effective_date ? new Date(document.effective_date) : undefined);
      setSupersedesDocumentId(document.supersedes_document_id || '');
    }
  }, [document]);
  
  // Filter out current document from supersedes options
  const supersedesOptions = useMemo(() => {
    return allDocuments.filter(d => d.id !== document?.id);
  }, [allDocuments, document?.id]);

  // Find documents that supersede this one (reverse lookup)
  const currentDocumentId = document?.id;
  const supersededBy = useMemo(() => {
    if (!currentDocumentId) return [];
    return allDocuments.filter((d) => d.supersedes_document_id === currentDocumentId);
  }, [allDocuments, currentDocumentId]);
  
  const handleAddTag = () => {
    const trimmed = newTag.trim().toLowerCase();
    if (trimmed && !tags.includes(trimmed)) {
      setTags([...tags, trimmed]);
      setNewTag('');
    }
  };
  
  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter(t => t !== tagToRemove));
  };
  
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddTag();
    }
  };
  
  const handleSave = async () => {
    if (!document) return;
    
    setIsSaving(true);
    
    try {
      const { error } = await supabase
        .from('documents')
        .update({
          tags: tags.length > 0 ? tags : null,
          version_label: versionLabel.trim() || null,
          effective_date: effectiveDate ? format(effectiveDate, 'yyyy-MM-dd') : null,
          supersedes_document_id: supersedesDocumentId || null,
          updated_at: new Date().toISOString(),
        })
        .eq('id', document.id);
      
      if (error) throw error;
      
      toast({
        title: 'Documento atualizado',
        description: 'Metadados salvos com sucesso.',
      });
      
      onSaved();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error('[DocumentEditor] Save error:', error);
      toast({
        title: 'Erro ao salvar',
        description: error instanceof Error ? error.message : 'Falha ao atualizar documento.',
        variant: 'destructive',
      });
    } finally {
      setIsSaving(false);
    }
  };
  
  if (!document) return null;
  
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <History className="w-5 h-5 text-primary" />
            Editar Metadados
          </DialogTitle>
          <DialogDescription className="truncate">
            {document.title}
          </DialogDescription>
        </DialogHeader>
        
        <div className="space-y-6 py-4">
          {/* Tags Section */}
          <div className="space-y-3">
            <Label className="flex items-center gap-2">
              <Tag className="w-4 h-4" />
              Tags
            </Label>
            <div className="flex flex-wrap gap-2 min-h-[32px] p-2 rounded-md border border-input bg-background">
              {tags.map((tag) => (
                <Badge
                  key={tag}
                  variant="secondary"
                  className="gap-1 pr-1"
                >
                  {tag}
                  <button
                    type="button"
                    onClick={() => handleRemoveTag(tag)}
                    className="ml-1 hover:bg-muted rounded-full p-0.5"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </Badge>
              ))}
              {tags.length === 0 && (
                <span className="text-sm text-muted-foreground">Nenhuma tag</span>
              )}
            </div>
            <div className="flex gap-2">
              <Input
                placeholder="Nova tag..."
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
                onKeyDown={handleKeyDown}
                className="flex-1"
              />
              <Button
                type="button"
                variant="outline"
                size="icon"
                onClick={handleAddTag}
                disabled={!newTag.trim()}
              >
                <Plus className="w-4 h-4" />
              </Button>
            </div>
          </div>
          
          {/* Version Label */}
          <div className="space-y-2">
            <Label htmlFor="version-label">Vers├úo</Label>
            <Input
              id="version-label"
              placeholder="Ex: v2.0, Edi├º├úo 2026, Rev. 3..."
              value={versionLabel}
              onChange={(e) => setVersionLabel(e.target.value)}
            />
          </div>
          
          {/* Effective Date */}
          <div className="space-y-2">
            <Label>Data de Vig├¬ncia</Label>
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  className={cn(
                    "w-full justify-start text-left font-normal",
                    !effectiveDate && "text-muted-foreground"
                  )}
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  {effectiveDate ? format(effectiveDate, "PPP", { locale: ptBR }) : "Selecionar data..."}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar
                  mode="single"
                  selected={effectiveDate}
                  onSelect={setEffectiveDate}
                  locale={ptBR}
                  initialFocus
                />
              </PopoverContent>
            </Popover>
            {effectiveDate && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => setEffectiveDate(undefined)}
                className="text-xs text-muted-foreground"
              >
                Limpar data
              </Button>
            )}
          </div>
          
          {/* Supersedes Document */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2">
              <Link2 className="w-4 h-4" />
              Substitui Documento
            </Label>
            <Select
              value={supersedesDocumentId}
              onValueChange={setSupersedesDocumentId}
            >
              <SelectTrigger>
                <SelectValue placeholder="Selecionar documento anterior..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">Nenhum</SelectItem>
                {supersedesOptions.map((doc) => (
                  <SelectItem key={doc.id} value={doc.id}>
                    {doc.title.length > 50 ? doc.title.substring(0, 50) + '...' : doc.title}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              Indica que este documento substitui uma vers├úo anterior
            </p>
          </div>
          
          {/* Superseded By (read-only info) */}
          {supersededBy.length > 0 && (
            <div className="space-y-2 p-3 rounded-md bg-amber-500/10 border border-amber-500/30">
              <Label className="text-amber-500 text-sm">ÔÜá´©Å Substitu├¡do por:</Label>
              <div className="space-y-1">
                {supersededBy.map((doc) => (
                  <p key={doc.id} className="text-sm text-amber-500/80">
                    ÔÇó {doc.title}
                  </p>
                ))}
              </div>
            </div>
          )}
        </div>
        
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isSaving}>
            Cancelar
          </Button>
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving ? (
              <>
                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                Salvando...
              </>
            ) : (
              <>
                <Save className="w-4 h-4 mr-2" />
                Salvar
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { FileDown, Check, Loader2 } from "lucide-react";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { toast } from "@/hooks/use-toast";
import type { ChatMessageSources, WebSourceData } from "@/hooks/useChat";

interface DownloadPdfButtonProps {
  userQuery: string;
  assistantResponse: string;
  timestamp: Date;
  sources?: ChatMessageSources;
  className?: string;
}

type PdfDependencies = {
  jsPDF: typeof import("jspdf").jsPDF;
  claraLogoPdf: string;
};

let pdfDependenciesPromise: Promise<PdfDependencies> | null = null;

function loadPdfDependencies(): Promise<PdfDependencies> {
  if (!pdfDependenciesPromise) {
    pdfDependenciesPromise = Promise.all([
      import("jspdf"),
      import("@/assets/clara-logo-pdf.png"),
    ]).then(([jspdfModule, logoModule]) => ({
      jsPDF: jspdfModule.jsPDF,
      claraLogoPdf: logoModule.default,
    }));
  }

  return pdfDependenciesPromise;
}

// Helper to extract URL from web source (works with both formats)
function getWebSourceUrl(source: WebSourceData | string): string {
  if (typeof source === 'string') return source;
  return source.url;
}

// Function to load image and convert to base64 for jsPDF
async function loadImageAsBase64(src: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        resolve(canvas.toDataURL("image/png"));
      } else {
        reject(new Error("Could not get canvas context"));
      }
    };
    img.onerror = () => reject(new Error("Could not load image"));
    img.src = src;
  });
}

export function DownloadPdfButton({ 
  userQuery, 
  assistantResponse, 
  timestamp,
  sources,
  className = "" 
}: DownloadPdfButtonProps) {
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloaded, setDownloaded] = useState(false);

  const handleDownload = useCallback(async () => {
    if (isDownloading) return;

    setIsDownloading(true);

    try {
      const { jsPDF, claraLogoPdf } = await loadPdfDependencies();
      const doc = new jsPDF();
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 20;
      const contentWidth = pageWidth - (margin * 2);
      let currentY = margin;
      
      // Helper to add new page if needed
      const checkPageBreak = (neededHeight: number) => {
        if (currentY + neededHeight > pageHeight - 30) {
          doc.addPage();
          currentY = margin;
          return true;
        }
        return false;
      };
      
      // Try to load and add logo image
      try {
        const logoBase64 = await loadImageAsBase64(claraLogoPdf);
        const logoWidth = 60;
        const logoHeight = 32;
        doc.addImage(logoBase64, "PNG", margin, currentY - 5, logoWidth, logoHeight);
        currentY += logoHeight + 5;
      } catch (error) {
        console.warn("Could not load logo image, using text fallback");
        doc.setTextColor(212, 165, 116);
        doc.setFontSize(16);
        doc.setFont("helvetica", "bold");
        doc.text("CLARA", margin, currentY);
        currentY += 6;
        doc.setFontSize(9);
        doc.setFont("helvetica", "normal");
        doc.setTextColor(80);
        doc.text("Consultora de Legisla├º├úo e Apoio a Rotinas Administrativas", margin, currentY);
        currentY += 8;
      }
      
      // Date
      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      doc.setTextColor(100);
      const formattedDate = timestamp.toLocaleString("pt-BR", {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit"
      });
      doc.text(`Gerado em: ${formattedDate}`, margin, currentY);
      currentY += 4;
      
      // Separator line
      doc.setDrawColor(200);
      doc.line(margin, currentY, pageWidth - margin, currentY);
      currentY += 10;
      
      // User query section
      doc.setTextColor(0);
      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text("Sua pergunta:", margin, currentY);
      currentY += 6;
      
      doc.setFontSize(11);
      doc.setFont("helvetica", "italic");
      doc.setTextColor(60);
      const queryLines = doc.splitTextToSize(`"${userQuery}"`, contentWidth);
      queryLines.forEach((line: string) => {
        checkPageBreak(6);
        doc.text(line, margin, currentY);
        currentY += 6;
      });
      currentY += 8;
      
      // Response section
      doc.setTextColor(0);
      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text("Resposta:", margin, currentY);
      currentY += 6;
      
      doc.setFontSize(11);
      doc.setFont("helvetica", "normal");
      
      // Clean markdown for plain text
      const cleanText = assistantResponse
        .replace(/\*\*(.+?)\*\*/g, "$1")
        .replace(/\*(.+?)\*/g, "$1")
        .replace(/`([^`]+)`/g, "$1")
        .replace(/```[\s\S]*?```/g, "")
        .replace(/#{1,6}\s/g, "")
        .replace(/\[([^\]]+)\]/g, "[$1]")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
      
      const responseLines = doc.splitTextToSize(cleanText, contentWidth);
      responseLines.forEach((line: string) => {
        checkPageBreak(6);
        doc.text(line, margin, currentY);
        currentY += 6;
      });
      
      // Sources section
      const hasLocalSources = sources?.local && sources.local.length > 0;
      const hasWebSources = sources?.web && sources.web.length > 0;
      
      if (hasLocalSources || hasWebSources) {
        currentY += 8;
        checkPageBreak(20);
        
        doc.setDrawColor(200);
        doc.line(margin, currentY, pageWidth - margin, currentY);
        currentY += 8;
        
        doc.setTextColor(0);
        doc.setFontSize(12);
        doc.setFont("helvetica", "bold");
        doc.text("Fontes Consultadas:", margin, currentY);
        currentY += 8;
        
        doc.setFontSize(10);
        doc.setFont("helvetica", "normal");
        doc.setTextColor(60);
        
        if (hasLocalSources) {
          sources.local.forEach((source) => {
            checkPageBreak(6);
            doc.text(`ÔÇó ${source}`, margin + 4, currentY);
            currentY += 6;
          });
        }
        
        if (hasWebSources) {
          if (hasLocalSources) currentY += 2;
          sources.web?.forEach((source) => {
            checkPageBreak(6);
            const url = getWebSourceUrl(source);
            const displayUrl = url.length > 60 ? url.substring(0, 57) + "..." : url;
            doc.text(`ÔÇó ${displayUrl}`, margin + 4, currentY);
            currentY += 6;
          });
        }
      }
      
      // Footer on last page
      const totalPages = doc.getNumberOfPages();
      for (let i = 1; i <= totalPages; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(
          "Documento gerado pela CLARA - Intelig├¬ncia Administrativa", 
          margin, 
          pageHeight - 10
        );
        doc.text(
          `P├ígina ${i} de ${totalPages}`,
          pageWidth - margin - 25,
          pageHeight - 10
        );
      }
      
      // Download
      const fileName = `clara-resposta-${timestamp.toISOString().split("T")[0]}.pdf`;
      doc.save(fileName);
      
      setDownloaded(true);
      toast({
        title: "PDF baixado!",
        description: "O arquivo foi salvo na sua pasta de downloads.",
      });
      
      setTimeout(() => setDownloaded(false), 2000);
    } catch (error) {
      console.error("Erro ao gerar PDF:", error);
      toast({
        title: "Erro ao gerar PDF",
        description: "N├úo foi poss├¡vel gerar o arquivo. Tente novamente.",
        variant: "destructive",
      });
    } finally {
      setIsDownloading(false);
    }
  }, [userQuery, assistantResponse, timestamp, sources, isDownloading]);

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          onClick={handleDownload}
          disabled={isDownloading}
          className={`action-btn ${downloaded ? "success" : ""} ${isDownloading ? "opacity-50 cursor-wait" : ""} ${className}`}
          aria-label={downloaded ? "PDF baixado!" : "Baixar como PDF"}
        >
          <AnimatePresence mode="wait">
            {isDownloading ? (
              <motion.span
                key="loading"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                transition={{ duration: 0.12 }}
                className="flex items-center gap-1.5"
              >
                <Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" />
                <span className="hidden sm:inline">Gerando...</span>
              </motion.span>
            ) : downloaded ? (
              <motion.span
                key="check"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                transition={{ duration: 0.12 }}
                className="flex items-center gap-1.5"
              >
                <Check className="w-3.5 h-3.5" aria-hidden="true" />
                <span className="hidden sm:inline">Baixado</span>
              </motion.span>
            ) : (
              <motion.span
                key="download"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                transition={{ duration: 0.12 }}
                className="flex items-center gap-1.5"
              >
                <FileDown className="w-3.5 h-3.5" aria-hidden="true" />
                <span className="hidden sm:inline">PDF</span>
              </motion.span>
            )}
          </AnimatePresence>
        </button>
      </TooltipTrigger>
      <TooltipContent side="top" className="text-xs">
        {isDownloading ? "Gerando PDF..." : downloaded ? "PDF baixado!" : "Baixar como PDF"}
      </TooltipContent>
    </Tooltip>
  );
}

import { useState, memo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ThumbsUp, ThumbsDown, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FeedbackModal } from "./FeedbackModal";
import { useFeedback } from "@/hooks/useFeedback";

interface FeedbackButtonsProps {
  queryId: string | null;
}

export const FeedbackButtons = memo(function FeedbackButtons({ queryId }: FeedbackButtonsProps) {
  const [feedbackGiven, setFeedbackGiven] = useState<"positive" | "negative" | null>(null);
  const [showModal, setShowModal] = useState(false);
  const { submitFeedback, isSubmitting } = useFeedback();

  // Don't show if no queryId available
  if (!queryId) return null;

  const handlePositive = async () => {
    if (feedbackGiven) return;
    
    const success = await submitFeedback({
      queryId,
      rating: true,
    });

    if (success) {
      setFeedbackGiven("positive");
    }
  };

  const handleNegative = () => {
    if (feedbackGiven) return;
    setShowModal(true);
  };

  const handleModalSubmit = async (category: string | undefined, text: string | undefined) => {
    const success = await submitFeedback({
      queryId,
      rating: false,
      category,
      feedbackText: text,
    });

    if (success) {
      setFeedbackGiven("negative");
    }
    setShowModal(false);
  };

  // Already gave feedback - show confirmation
  if (feedbackGiven) {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        className="flex items-center gap-1.5 text-xs text-muted-foreground"
      >
        <Check className="w-3.5 h-3.5 text-primary" />
        <span>Obrigado!</span>
      </motion.div>
    );
  }

  return (
    <>
      <div className="flex items-center gap-1">
        <Button
          variant="ghost"
          size="sm"
          onClick={handlePositive}
          disabled={isSubmitting}
          className="h-7 w-7 p-0 text-muted-foreground hover:text-primary hover:bg-primary/10"
          aria-label="Feedback positivo"
        >
          <ThumbsUp className="w-3.5 h-3.5" />
        </Button>
        <Button
          variant="ghost"
          size="sm"
          onClick={handleNegative}
          disabled={isSubmitting}
          className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive hover:bg-destructive/10"
          aria-label="Feedback negativo"
        >
          <ThumbsDown className="w-3.5 h-3.5" />
        </Button>
      </div>

      <FeedbackModal
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSubmit={handleModalSubmit}
        isSubmitting={isSubmitting}
      />
    </>
  );
});

