                            <div className="flex items-center gap-2 flex-shrink-0">
                              {/* Edit Metadata Button */}
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    onClick={() => {
                                      setDocumentToEdit(doc);
