                              {canRetry && !canProcess && (
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      onClick={() => handleRetryProcessing(doc.id, doc.title)}
