                                    </p>
                                  </TooltipContent>
                                </Tooltip>
                              )}
                              
                              {/* Delete Button */}
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() => {
                                  setDocumentToDelete(doc);
                                  setDeleteDialogOpen(true);
