                Tem certeza que deseja remover "{documentToDelete?.title}"? Esta a├º├úo n├úo pode ser desfeita.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancelar</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleDelete}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                Remover
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* OCR Dialog for Scanned PDFs */}
        <AlertDialog open={showOcrDialog} onOpenChange={(open) => {
          if (!open && !ocrProcessing) {
            setShowOcrDialog(false);
            setOcrFile(null);
          }
        }}>
          <AlertDialogContent className="glass-card">
            <AlertDialogHeader>
              <div className="flex items-center gap-3 mb-2">
                <div className="w-12 h-12 rounded-lg bg-amber-500/20 flex items-center justify-center">
                  <FileWarning className="w-6 h-6 text-amber-500" />
                </div>
                <div>
                  <AlertDialogTitle>PDF Escaneado Detectado</AlertDialogTitle>
